/**
 * @description One background run of a Response Handler Class for IntegrationHubBusiness: builds the context from the
 * stored body (or its File), runs the handler, and returns the update (Done with the result, or Failed with the error).
 * @group Integration Hub
 */
public with sharing class IntegrationHubBusinessRun {

    /**
     * @description Runs the handler for one transaction. Changes the handler made are rolled back when it fails.
     * @param t the transaction
     * @param ev its event
     * @return the update: the fields the handler changed plus the business fields
     */
    public static IH_Transaction__c runOne(IH_Transaction__c t, IH_Event__c ev) {
        IH_Transaction__c before = t.clone(true, true, true, true);
        IntegrationHub.ResponseContext ctx = context(t);
        String className = ev == null ? null : ev.Response_Handler_Class__c;
        Savepoint sp = Database.setSavepoint();
        String error = String.isBlank(className) ? 'The event has no Response Handler Class.'
            : IntegrationHubOutcome.runHandler(className, ctx);
        IH_Transaction__c row;
        if (error == null) {
            row = changes(before, ctx.txn);
            row.Business_Status__c = IntegrationHubBusiness.DONE;
            row.Business_Result__c = IntegrationHub.clip(ctx.result, 255);
            row.Business_Error__c = null;
        } else {
            Database.rollback(sp);
            row = new IH_Transaction__c(Id = t.Id, Business_Status__c = IntegrationHubBusiness.FAILED, Business_Result__c = null,
                Business_Error__c = IntegrationHub.clip(error, 32768));
        }
        row.Business_Runs__c = (t.Business_Runs__c == null ? 0 : t.Business_Runs__c) + 1;
        return row;
    }

    /**
     * @description The handler's input from a stored transaction: the callback when there is one, otherwise the answer;
     * the full body comes from the File when the field was cut.
     * @param t the transaction
     * @return the context
     */
    public static IntegrationHub.ResponseContext context(IH_Transaction__c t) {
        IntegrationHub.ResponseContext ctx = new IntegrationHub.ResponseContext();
        ctx.txn = t;
        ctx.transactionId = t.Id;
        ctx.relatedRecordId = t.Related_Record_Id__c;
        ctx.isCallback = String.isNotBlank(t.Callback_Body__c);
        ctx.httpStatus = ctx.isCallback || t.Http_Status_Code__c == null ? null : t.Http_Status_Code__c.intValue();
        ctx.body = ctx.isCallback
            ? IntegrationHubBodyFiles.fullBody(t.Id, IntegrationHubBodyFiles.CALLBACK_PREFIX, t.Callback_Body__c)
            : IntegrationHubBodyFiles.fullBody(t.Id, IntegrationHubBodyFiles.RESPONSE_PREFIX, t.Response_Body__c);
        ctx.data = IntegrationHubBusiness.dataOf(ctx.body);
        return ctx;
    }

    /* Only the fields the handler changed are written, so values changed meanwhile (e.g. Status by a callback) are kept. */
    private static IH_Transaction__c changes(IH_Transaction__c before, IH_Transaction__c after) {
        IH_Transaction__c row = new IH_Transaction__c(Id = before.Id);
        Map<String, Object> old = before.getPopulatedFieldsAsMap();
        for (String field : after.getPopulatedFieldsAsMap().keySet()) {
            Object value = after.get(field);
            if (field != 'Id' && field != 'Name' && (!old.containsKey(field) || value != old.get(field))) {
                row.put(field, value);
            }
        }
        return row;
    }
}
